import { hexlify } from "@ethersproject/bytes";
import { parseUnits } from "@ethersproject/units";
import { notification } from "antd";
import Notify from "bnc-notify";
import { BLOCKNATIVE_DAPPID } from "../constants";

// this should probably just be renamed to "notifier"
// it is basically just a wrapper around BlockNative's wonderful Notify.js
// https://docs.blocknative.com/notify

export default function Transactor(provider, gasPrice, etherscan, targetChainId) {
  if (typeof provider !== "undefined") {
    // eslint-disable-next-line consistent-return
    return async tx => {
      const signer = provider.getSigner();
      const network = await provider.getNetwork();
      console.log("network", network);

      // Safety check - if targetChainId is provided, ensure we're on the right network
      if (targetChainId && network.chainId !== targetChainId) {
        // Get network names for better error messages
        const getCurrentNetworkName = (chainId) => {
          // Common networks
          const networks = {
            1: "Ethereum Mainnet",
            5: "Goerli Testnet",
            80001: "Mumbai Testnet",
            80002: "Polygon Amoy Testnet",
            31337: "Hardhat Local",
            1337: "Localhost"
          };
          return networks[chainId] || `Chain ID ${chainId}`;
        };

        const targetNetworkName = getCurrentNetworkName(targetChainId);
        const currentNetworkName = getCurrentNetworkName(network.chainId);

        // Show clear error and prevent transaction
        notification.error({
          message: "⚠️ Network Mismatch ⚠️",
          description: `You are trying to send a transaction on ${currentNetworkName} but this app requires ${targetNetworkName}. Please switch your wallet network.`,
          duration: 10,
        });
        
        // Return early to prevent transaction from being sent
        return null;
      }
      
      const options = {
        dappId: BLOCKNATIVE_DAPPID, // GET YOUR OWN KEY AT https://account.blocknative.com
        system: "ethereum",
        networkId: network.chainId,
        // darkMode: Boolean, // (default: false)
        transactionHandler: txInformation => {
          console.log("HANDLE TX", txInformation);
        },
      };
      const notify = Notify(options);

      let etherscanNetwork = "";
      if (network.name && network.chainId > 1) {
        etherscanNetwork = network.name + ".";
      }

      let etherscanTxUrl = "https://" + etherscanNetwork + "etherscan.io/tx/";
      if (network.chainId === 100) {
        etherscanTxUrl = "https://blockscout.com/poa/xdai/tx/";
      }

      try {
        let result;
        if (tx instanceof Promise) {
          console.log("TX AWAITING", tx);
          result = await tx;
          console.log("TX GOT RESULT: ", result);
        } else {
          if (!tx.gasPrice) {
            tx.gasPrice = gasPrice || parseUnits("4.1", "gwei");
          }
          if (!tx.gasLimit) {
            tx.gasLimit = hexlify(120000);
          }
          console.log("RUNNING TX", tx);
          result = await signer.sendTransaction(tx);
        }
        console.log("RESULT:", result);
        // console.log("Notify", notify);

        // if it is a valid Notify.js network, use that, if not, just send a default notification
        if ([1, 3, 4, 5, 42, 100].indexOf(network.chainId) >= 0) {
          const { emitter } = notify.hash(result.hash);
          emitter.on("all", transaction => {
            return {
              onclick: () => window.open((etherscan || etherscanTxUrl) + transaction.hash),
            };
          });
        } else {
          notification.info({
            message: "Local Transaction Sent",
            description: result.hash,
            placement: "bottomRight",
          });
        }

        return result;
      } catch (e) {
        console.log(e);
        console.log("Transaction Error:", e.message);
        notification.error({
          message: "Transaction Error",
          description: e.message,
        });
      }
    };
  }
}
