import React, { useEffect, useState, useRef } from "react";
import { Modal, Row, Col, Button, Space, Spin, Typography, Switch, Input } from "antd";
import { PlayCircleOutlined, PauseCircleOutlined, StepForwardOutlined, StepBackwardOutlined } from "@ant-design/icons";
import Win95Slider from "./Win95Slider";

const { Text } = Typography;

function AnimationModal(props) {
  const { visible, onClose, allCollectibles, initialEpoch = null } = props;

  // State for animation control
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentGeneration, setCurrentGeneration] = useState(0);
  const [speed, setSpeed] = useState(1000); // milliseconds between frames
  const [showDetails, setShowDetails] = useState(true);

  // We're now using initialEpoch directly instead of allowing it to be changed
  const selectedEpoch = initialEpoch;

  // Refs
  const animationRef = useRef(null);
  const tokensByEpoch = useRef({});
  const maxGeneration = useRef(0);

  // Reset state when modal opens
  useEffect(() => {
    if (visible) {
      setIsPlaying(false);
      // Don't reset generation to 0 here - it will be set when validGenerations is available
    } else {
      // Stop animation when modal closes
      if (animationRef.current) {
        clearInterval(animationRef.current);
        animationRef.current = null;
      }
    }
  }, [visible]);

  // Get valid generations for the current epoch - Moved up to fix initialization order
  const validGenerations = React.useMemo(() => {
    if (!selectedEpoch) return [];

    const epochTokens = tokensByEpoch.current[selectedEpoch] || {};
    return Object.keys(epochTokens)
      .map(g => parseInt(g))
      .sort((a, b) => a - b);
  }, [selectedEpoch]);
  
  // Set the initial generation when valid generations are available
  useEffect(() => {
    if (validGenerations.length > 0 && (currentGeneration === 0 || !validGenerations.includes(currentGeneration))) {
      // Set to the minimum valid generation (usually 0 or 1)
      setCurrentGeneration(Math.min(...validGenerations));
    }
  }, [validGenerations, selectedEpoch, currentGeneration]);

  // We no longer need the availableEpochs since we're using initialEpoch directly

  // Group tokens by epoch and generation
  useEffect(() => {
    if (!allCollectibles || allCollectibles.length === 0) return;

    const epochMap = {};
    let globalMaxGen = 0;

    allCollectibles.forEach(item => {
      if (!item.attributes) return;

      // Find epoch and generation attributes
      const epochAttr = item.attributes.find(attr => attr.trait_type === "epoch");
      const genAttr = item.attributes.find(attr => attr.trait_type === "generation");

      if (epochAttr && genAttr) {
        const epoch = epochAttr.value.replace("#", "");
        const generation = parseInt(genAttr.value.replace("#", ""));

        // Track max generation
        if (generation > globalMaxGen) {
          globalMaxGen = generation;
        }

        // Initialize epoch map if needed
        if (!epochMap[epoch]) {
          epochMap[epoch] = {};
        }

        // Add token to epoch and generation
        if (!epochMap[epoch][generation]) {
          epochMap[epoch][generation] = [];
        }

        epochMap[epoch][generation].push(item);
      }
    });

    tokensByEpoch.current = epochMap;
    maxGeneration.current = globalMaxGen;

    // Since we're using initialEpoch directly, we don't need to handle epoch selection anymore
  }, [allCollectibles]);

  // No longer need auto-selection since we're using initialEpoch directly

  // Animation loop
  useEffect(() => {
    if (!isPlaying || !selectedEpoch) return;

    // Clear any existing animation
    if (animationRef.current) {
      clearInterval(animationRef.current);
    }

    // Get the max generation for this epoch
    const epochTokens = tokensByEpoch.current[selectedEpoch] || {};
    const generations = Object.keys(epochTokens).map(g => parseInt(g));

    if (generations.length === 0) {
      setIsPlaying(false);
      return;
    }

    const maxGen = Math.max(...generations);

    // Start animation loop
    animationRef.current = setInterval(() => {
      setCurrentGeneration(prev => {
        // Find next valid generation
        let nextGen = prev + 1;

        // Loop back to beginning if we exceed max
        if (nextGen > maxGen) {
          nextGen = Math.min(...generations);
        }

        // Skip generations that don't have tokens
        while (!epochTokens[nextGen] && nextGen <= maxGen) {
          nextGen++;
        }

        // If we went past the end, loop back to beginning
        if (nextGen > maxGen) {
          nextGen = Math.min(...generations);
        }

        return nextGen;
      });
    }, speed);

    return () => {
      if (animationRef.current) {
        clearInterval(animationRef.current);
      }
    };
  }, [isPlaying, selectedEpoch, speed]);

  // Handle stepping through generations manually
  const handleStepForward = () => {
    if (!selectedEpoch) return;

    const epochTokens = tokensByEpoch.current[selectedEpoch] || {};
    const generations = Object.keys(epochTokens).map(g => parseInt(g));

    if (generations.length === 0) return;

    const maxGen = Math.max(...generations);

    setCurrentGeneration(prev => {
      // Find next valid generation
      let nextGen = prev + 1;

      // Loop back to beginning if we exceed max
      if (nextGen > maxGen) {
        nextGen = Math.min(...generations);
      }

      // Skip generations that don't have tokens
      while (!epochTokens[nextGen] && nextGen <= maxGen) {
        nextGen++;
      }

      // If we went past the end, loop back to beginning
      if (nextGen > maxGen) {
        nextGen = Math.min(...generations);
      }

      return nextGen;
    });
  };

  const handleStepBackward = () => {
    if (!selectedEpoch) return;

    const epochTokens = tokensByEpoch.current[selectedEpoch] || {};
    const generations = Object.keys(epochTokens).map(g => parseInt(g));

    if (generations.length === 0) return;

    const minGen = Math.min(...generations);
    const maxGen = Math.max(...generations);

    setCurrentGeneration(prev => {
      // Find previous valid generation
      let prevGen = prev - 1;

      // Loop to end if we go below min
      if (prevGen < minGen) {
        prevGen = maxGen;
      }

      // Skip generations that don't have tokens
      while (!epochTokens[prevGen] && prevGen >= minGen) {
        prevGen--;
      }

      // If we went past the beginning, loop to end
      if (prevGen < minGen) {
        prevGen = maxGen;
      }

      return prevGen;
    });
  };

  // Get current token to display
  const currentToken = React.useMemo(() => {
    if (!selectedEpoch) return null;

    const epochTokens = tokensByEpoch.current[selectedEpoch] || {};

    // Handle case where currentGeneration is 0 (or any valid generation)
    let generationToUse = currentGeneration;

    // If the specified generation doesn't have tokens, try to find a valid one
    if (!epochTokens[generationToUse] && validGenerations.length > 0) {
      generationToUse = Math.min(...validGenerations);
    }

    const generationTokens = epochTokens[generationToUse] || [];

    if (generationTokens.length === 0) return null;

    // Just pick the first token for this generation
    return generationTokens[0];
  }, [selectedEpoch, currentGeneration, validGenerations]);

  // Get the first generation token for the selected epoch
  const getFirstGenerationToken = () => {
    if (!selectedEpoch) return null;

    const epochTokens = tokensByEpoch.current[selectedEpoch] || {};
    const generations = Object.keys(epochTokens)
      .map(g => parseInt(g))
      .sort((a, b) => a - b);

    if (generations.length === 0) return null;

    // Get the first generation
    const firstGen = generations[0];
    const firstGenTokens = epochTokens[firstGen] || [];

    if (firstGenTokens.length === 0) return null;

    // Return the first token for this generation
    return firstGenTokens[0];
  };

  // Format animation details
  const formatDetails = () => {
    // Use either currentToken or firstGenerationToken
    const tokenToDisplay = currentToken || getFirstGenerationToken();

    if (!tokenToDisplay || !tokenToDisplay.attributes) return "No token selected";

    // Format attributes for better mobile display
    const attrLines = tokenToDisplay.attributes.map(attr => `${attr.trait_type}: ${attr.value}`);

    // Join with line breaks for better mobile viewing
    return (
      <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", gap: "8px" }}>
        {attrLines.map((line, index) => (
          <span
            key={index}
            style={{
              background: "#FFFFFF",
              padding: "4px 8px",
              border: "2px solid",
              borderColor: "#404040 #FFFFFF #FFFFFF #404040",
              boxShadow: "1px 1px 0 #000000",
              fontSize: "12px",
              fontFamily: "'PixelOperator', monospace",
            }}
          >
            {line}
          </span>
        ))}
      </div>
    );
  };

  /* This duplicate definition has been moved to line 40 to fix the initialization order issue */

  // Calculate simple min/max slider marks
  const sliderMarks = React.useMemo(() => {
    if (validGenerations.length === 0) return {};

    const minGen = Math.min(...validGenerations);
    const maxGen = Math.max(...validGenerations);

    return {
      [minGen]: "",
      [maxGen]: "",
    };
  }, [validGenerations]);

  // Handle generation input change
  const handleGenerationInputChange = value => {
    if (value === "" || isNaN(value)) return;

    const numValue = parseInt(value);
    const minGen = Math.min(...validGenerations);
    const maxGen = Math.max(...validGenerations);

    // Ensure value is within valid range
    if (numValue >= minGen && numValue <= maxGen) {
      // Find closest valid generation
      let closestGen = validGenerations.reduce((prev, curr) =>
        Math.abs(curr - numValue) < Math.abs(prev - numValue) ? curr : prev,
      );

      setCurrentGeneration(closestGen);
    }
  };

  // Style to customize modal appearance
  const modalCustomStyle = `
    /* Hide the default close button */
    .ant-modal-close {
      display: none !important;
    }
    
    /* Remove box shadow but keep transparent background */
    .ant-modal-content {
      box-shadow: none !important;
      background-color: transparent !important;
      padding: 0 !important;
    }
    
    /* Transparent body */
    .ant-modal-body {
      background-color: transparent !important;
      padding: 0 !important;
    }
  `;

  return (
    <>
      <style>{modalCustomStyle}</style>
      <Modal
        title={null} // Remove default title
        open={visible}
        onCancel={onClose}
        footer={null}
        closeIcon={null}
        width={900}
        style={{
          top: 20,
          maxWidth: "95vw",
          padding: 0,
          border: "none",
          backgroundColor: "#FFFFFF",
        }}
        bodyStyle={{
          padding: 0,
          margin: 0,
          maxHeight: "80vh",
          overflow: "visible", // Allow the custom title bar to be visible
          backgroundColor: "#FFFFFF",
          border: "none",
        }}
        centered
        maskStyle={{ backgroundColor: "rgba(0, 0, 0, 0.7)" }}
        wrapClassName="win95-modal-wrapper"
        modalRender={modal => (
          <div
            style={{
              background: "#FFFFFF",
              border: "2px solid",
              borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
              padding: 0,
              boxSizing: "border-box",
              overflow: "hidden",
              backgroundColor: "#FFFFFF",
              boxShadow: "1px 1px 0 #000000",
            }}
          >
            {/* Custom title bar */}
            <div
              style={{
                height: "22px",
                background: "#000080",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                padding: "0",
                borderBottom: "1px solid #000000",
                position: "relative",
                borderTop: "1px solid #FFFFFF",
                borderLeft: "1px solid #FFFFFF",
              }}
            >
              {/* Control box */}
              <div
                style={{
                  position: "absolute",
                  left: "2px",
                  top: "3px",
                  width: "16px",
                  height: "16px",
                  background: "#C0C0C0",
                  border: "2px solid",
                  borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  cursor: "pointer",
                }}
                onClick={onClose}
              >
                <div
                  style={{
                    width: "8px",
                    height: "2px",
                    background: "#000000",
                    position: "absolute",
                  }}
                ></div>
              </div>

              <div
                style={{
                  color: "#FFFFFF",
                  fontSize: "12pt",
                  fontWeight: "normal",
                  fontFamily: "'04b_03', monospace",
                  letterSpacing: "1px",
                  textTransform: "uppercase",
                  paddingTop: "3px",
                  textAlign: "center",
                  flexGrow: 1,
                }}
              >
                g4m3 0f l1f3 Animation - Epoch {selectedEpoch || "?"}
              </div>

              {/* Close button */}
              <div
                style={{
                  position: "absolute",
                  right: "2px",
                  top: "3px",
                  width: "16px",
                  height: "16px",
                  background: "#C0C0C0",
                  border: "2px solid",
                  borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  cursor: "pointer",
                }}
                onClick={onClose}
              >
                <div
                  style={{
                    position: "relative",
                    width: "8px",
                    height: "8px",
                  }}
                >
                  <div
                    style={{
                      position: "absolute",
                      width: "10px",
                      height: "2px",
                      background: "#000000",
                      top: "3px",
                      left: "-1px",
                      transform: "rotate(45deg)",
                    }}
                  ></div>
                  <div
                    style={{
                      position: "absolute",
                      width: "10px",
                      height: "2px",
                      background: "#000000",
                      top: "3px",
                      left: "-1px",
                      transform: "rotate(-45deg)",
                    }}
                  ></div>
                </div>
              </div>
            </div>

            {/* Content area */}
            <div
              style={{
                background: "#FFFFFF",
                margin: 0,
                padding: "12px",
                fontFamily: "'PixelOperator', monospace",
                backgroundColor: "#FFFFFF",
              }}
            >
              {modal}
            </div>
          </div>
        )}
        className="win311-window"
      >
        {/* Vertical stacking of components */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "12px",
            background: "#FFFFFF",
            padding: "10px",
          }}
        >
          {/* 1. Top Section: Controls */}
          <div style={{ marginBottom: "8px" }}>
            <Row gutter={[16, 8]}>
              <Col xs={24} sm={6}>
                <div
                  style={{
                    fontSize: "12px",
                    fontWeight: "bold",
                    marginBottom: "6px",
                    borderBottom: "1px solid #000000",
                    paddingBottom: "2px",
                    color: "#000000",
                    textAlign: "left",
                  }}
                >
                  Animation Speed
                </div>

                <div style={{ display: "flex", alignItems: "center", marginBottom: "5px" }}>
                  <span
                    style={{
                      fontSize: "12px",
                      fontWeight: "bold",
                      marginRight: "4px",
                      color: "#000000",
                      minWidth: "30px",
                    }}
                  >
                    Slow
                  </span>

                  <div style={{ position: "relative", flex: 1, display: "flex", alignItems: "center", height: "26px" }}>
                    {/* Left Arrow Button */}
                    <button
                      onClick={() => setSpeed(Math.min(2000, speed + 100))}
                      style={{
                        width: "26px",
                        height: "26px",
                        background: "#C0C0C0",
                        color: "#000000",
                        border: "2px solid",
                        borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                        boxShadow: "1px 1px 0 #000000",
                        padding: 0,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        cursor: "pointer",
                        userSelect: "none",
                        zIndex: 1,
                        marginRight: "0",
                        fontSize: "14px",
                        fontWeight: "bold",
                      }}
                    >
                      ←
                    </button>

                    <div style={{ flex: 1 }}>
                      <Win95Slider
                        min={100}
                        max={2000}
                        step={100}
                        value={speed}
                        onChange={value => setSpeed(value)}
                        reverse
                      />
                    </div>

                    {/* Right Arrow Button */}
                    <button
                      onClick={() => setSpeed(Math.max(100, speed - 100))}
                      style={{
                        width: "26px",
                        height: "26px",
                        background: "#C0C0C0",
                        color: "#000000",
                        border: "2px solid",
                        borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                        boxShadow: "1px 1px 0 #000000",
                        padding: 0,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        cursor: "pointer",
                        userSelect: "none",
                        zIndex: 1,
                        marginLeft: "0",
                        fontSize: "14px",
                        fontWeight: "bold",
                      }}
                    >
                      →
                    </button>
                  </div>

                  <span
                    style={{
                      fontSize: "12px",
                      fontWeight: "bold",
                      marginLeft: "4px",
                      color: "#000000",
                      minWidth: "30px",
                      textAlign: "right",
                    }}
                  >
                    Fast
                  </span>
                </div>
              </Col>

              <Col xs={24} sm={12}>
                <div
                  style={{
                    fontSize: "12px",
                    fontWeight: "bold",
                    marginBottom: "6px",
                    borderBottom: "1px solid #000000",
                    paddingBottom: "2px",
                    color: "#000000",
                    textAlign: "left",
                  }}
                >
                  Generation Control
                </div>

                <div style={{ display: "flex", alignItems: "center", gap: "4px" }}>
                  <span
                    style={{
                      fontSize: "12px",
                      fontWeight: "bold",
                      color: "#000000",
                      minWidth: "80px",
                    }}
                  >
                    Generation:
                  </span>

                  <div style={{ position: "relative", flex: 1, display: "flex", alignItems: "center", height: "26px" }}>
                    {/* Left Arrow Button */}
                    <button
                      onClick={handleStepBackward}
                      disabled={!selectedEpoch || validGenerations.length === 0}
                      style={{
                        width: "26px",
                        height: "26px",
                        background: "#C0C0C0",
                        color: "#000000",
                        border: "2px solid",
                        borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                        boxShadow: "1px 1px 0 #000000",
                        padding: 0,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        cursor: selectedEpoch && validGenerations.length > 0 ? "pointer" : "default",
                        opacity: selectedEpoch && validGenerations.length > 0 ? 1 : 0.5,
                        userSelect: "none",
                        zIndex: 1,
                        marginRight: "0",
                        fontSize: "14px",
                        fontWeight: "bold",
                      }}
                    >
                      ←
                    </button>

                    <div style={{ flex: 1 }}>
                      <Win95Slider
                        value={currentGeneration}
                        onChange={value => setCurrentGeneration(value)}
                        min={validGenerations.length > 0 ? Math.min(...validGenerations) : 0}
                        max={validGenerations.length > 0 ? Math.max(...validGenerations) : 0}
                        disabled={validGenerations.length === 0}
                      />
                    </div>

                    {/* Right Arrow Button */}
                    <button
                      onClick={handleStepForward}
                      disabled={!selectedEpoch || validGenerations.length === 0}
                      style={{
                        width: "26px",
                        height: "26px",
                        background: "#C0C0C0",
                        color: "#000000",
                        border: "2px solid",
                        borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                        boxShadow: "1px 1px 0 #000000",
                        padding: 0,
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                        cursor: selectedEpoch && validGenerations.length > 0 ? "pointer" : "default",
                        opacity: selectedEpoch && validGenerations.length > 0 ? 1 : 0.5,
                        userSelect: "none",
                        zIndex: 1,
                        marginLeft: "0",
                        fontSize: "14px",
                        fontWeight: "bold",
                      }}
                    >
                      →
                    </button>
                  </div>

                  <input
                    value={currentGeneration}
                    onChange={e => handleGenerationInputChange(e.target.value)}
                    disabled={validGenerations.length === 0}
                    style={{
                      width: "50px",
                      height: "26px",
                      background: "#FFFFFF",
                      color: "#000000",
                      borderRadius: 0,
                      border: "2px solid",
                      borderColor: "#404040 #FFFFFF #FFFFFF #404040",
                      padding: "0 3px",
                      boxSizing: "border-box",
                      fontFamily: "'PixelOperator', monospace",
                      fontSize: "12px",
                      fontWeight: "bold",
                      textAlign: "right",
                      marginLeft: "7px",
                    }}
                    type="number"
                    min={Math.min(...(validGenerations.length > 0 ? validGenerations : [0]))}
                    max={Math.max(...(validGenerations.length > 0 ? validGenerations : [0]))}
                  />
                </div>
              </Col>

              <Col xs={24} sm={6}>
                <div
                  style={{
                    fontSize: "12px",
                    fontWeight: "bold",
                    marginBottom: "6px",
                    borderBottom: "1px solid #000000",
                    paddingBottom: "2px",
                    color: "#000000",
                    textAlign: "left",
                  }}
                >
                  Details
                </div>

                <div style={{ display: "flex", alignItems: "center" }}>
                  <span
                    style={{
                      fontSize: "12px",
                      fontWeight: "bold",
                      marginRight: "8px",
                      color: "#000000",
                    }}
                  >
                    Show:
                  </span>

                  <div style={{ display: "flex", alignItems: "center" }}>
                    <label
                      style={{
                        display: "flex",
                        alignItems: "center",
                        marginRight: "8px",
                        cursor: "pointer",
                      }}
                      onClick={() => setShowDetails(true)}
                    >
                      <div
                        style={{
                          width: "14px",
                          height: "14px",
                          border: "2px solid",
                          borderColor: "#404040 #FFFFFF #FFFFFF #404040",
                          backgroundColor: showDetails ? "#C0C0C0" : "#FFFFFF",
                          position: "relative",
                          marginRight: "4px",
                          display: "flex",
                          justifyContent: "center",
                          alignItems: "center",
                        }}
                      >
                        {showDetails && (
                          <div
                            style={{
                              width: "8px",
                              height: "8px",
                              backgroundColor: "#000",
                            }}
                          />
                        )}
                      </div>
                      <span
                        style={{
                          fontSize: "12px",
                          fontFamily: "'PixelOperator', monospace",
                          color: "#000",
                          fontWeight: "bold",
                        }}
                      >
                        Yes
                      </span>
                    </label>

                    <label
                      style={{
                        display: "flex",
                        alignItems: "center",
                        cursor: "pointer",
                      }}
                      onClick={() => setShowDetails(false)}
                    >
                      <div
                        style={{
                          width: "14px",
                          height: "14px",
                          border: "2px solid",
                          borderColor: "#404040 #FFFFFF #FFFFFF #404040",
                          backgroundColor: !showDetails ? "#C0C0C0" : "#FFFFFF",
                          position: "relative",
                          marginRight: "4px",
                          display: "flex",
                          justifyContent: "center",
                          alignItems: "center",
                        }}
                      >
                        {!showDetails && (
                          <div
                            style={{
                              width: "8px",
                              height: "8px",
                              backgroundColor: "#000",
                            }}
                          />
                        )}
                      </div>
                      <span
                        style={{
                          fontSize: "12px",
                          fontFamily: "'PixelOperator', monospace",
                          color: "#000",
                          fontWeight: "bold",
                        }}
                      >
                        No
                      </span>
                    </label>
                  </div>
                </div>
              </Col>

              <Col span={24} style={{ marginTop: "8px" }}>
                <div
                  style={{
                    display: "flex",
                    justifyContent: "center",
                    gap: "8px",
                  }}
                >
                  <button
                    onClick={() => setIsPlaying(!isPlaying)}
                    disabled={!selectedEpoch || validGenerations.length === 0}
                    style={{
                      width: "80px",
                      height: "32px",
                      background: "#C0C0C0",
                      color: "#000000",
                      fontSize: "12pt",
                      border: "2px solid",
                      borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                      boxShadow: "1px 1px 0 #000000",
                      padding: "0 10px",
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      cursor: selectedEpoch && validGenerations.length > 0 ? "pointer" : "default",
                      opacity: selectedEpoch && validGenerations.length > 0 ? 1 : 0.5,
                      fontWeight: "bold",
                      fontFamily: "'PixelOperator', monospace",
                      userSelect: "none",
                    }}
                  >
                    {isPlaying ? "Stop" : "Play"}
                  </button>
                </div>
              </Col>
            </Row>
          </div>

          {/* 2. Middle Section: Animation Container */}
          <div style={{ position: "relative" }}>
            <div
              className="animation-container"
              style={{
                width: "100%",
                height: "calc(60vh - 60px)",
                minHeight: "350px",
                backgroundColor: "#000000",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                overflow: "hidden",
                border: "2px solid",
                borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                boxShadow: "1px 1px 0 #000000",
                marginBottom: "12px",
              }}
            >
              {currentToken ? (
                <>
                  <img
                    src={currentToken.image}
                    alt={`Epoch ${selectedEpoch} Generation ${currentGeneration}`}
                    style={{
                      maxWidth: "100%",
                      maxHeight: "100%",
                      objectFit: "contain",
                    }}
                  />
                </>
              ) : selectedEpoch ? (
                <>
                  {(() => {
                    const firstGenToken = getFirstGenerationToken();
                    if (firstGenToken) {
                      // Set the current generation to 0 (or the first available generation)
                      // and display that token without overlay
                      if (currentGeneration <= 0 && validGenerations.length > 0) {
                        // If validGenerations exists but generation is not set,
                        // set it to the first available generation
                        setTimeout(() => {
                          setCurrentGeneration(Math.min(...validGenerations));
                        }, 0);
                      }

                      return (
                        <img
                          src={firstGenToken.image}
                          alt={`Epoch ${selectedEpoch} Generation ${Math.min(...validGenerations)}`}
                          style={{
                            maxWidth: "100%",
                            maxHeight: "100%",
                            objectFit: "contain",
                          }}
                        />
                      );
                    } else {
                      return (
                        <span
                          style={{
                            color: "#666",
                            fontFamily: "'PixelOperator', monospace",
                            fontSize: "12px",
                            fontWeight: "bold",
                          }}
                        >
                          No tokens found for this epoch
                        </span>
                      );
                    }
                  })()}
                </>
              ) : (
                <span
                  style={{
                    color: "#666",
                    fontFamily: "'PixelOperator', monospace",
                    fontSize: "12px",
                    fontWeight: "bold",
                  }}
                >
                  Select an epoch to begin
                </span>
              )}
            </div>
          </div>

          {/* 3. Bottom Section: Details Panel (if shown) */}
          {showDetails && selectedEpoch && (currentToken || getFirstGenerationToken()) && (
            <div
              className="details-panel"
              style={{
                padding: "0",
                backgroundColor: "#FFFFFF",
                color: "#000",
                border: "none",
                borderColor: "#FFFFFF #404040 #404040 #FFFFFF",
                boxShadow: "0px 0px 0 #000000",
                borderRadius: "0",
                maxHeight: "120px",
                width: "100%",
                marginTop: "0",
              }}
            >
              {/* Windows-style title bar for details */}
              <div
                style={{
                  borderBottom: "1px solid #000000",
                  paddingBottom: "2px",
                  padding: "4px 8px",
                  position: "relative",
                }}
              >
                <div
                  style={{
                    color: "#000000",
                    fontSize: "12px",
                    fontWeight: "bold",
                    fontFamily: "'PixelOperator', monospace",
                    textAlign: "left",
                  }}
                >
                  Token #{(currentToken || getFirstGenerationToken())?.id || "?"} Details
                </div>
              </div>

              {/* Details content */}
              <div
                style={{
                  padding: "8px",
                  backgroundColor: "#FFFFFF",
                  overflowY: "auto",
                  maxHeight: "90px",
                  fontFamily: "'PixelOperator', monospace",
                  fontSize: "12px",
                  fontWeight: "bold",
                  textAlign: "center",
                }}
              >
                {formatDetails()}
              </div>
            </div>
          )}
        </div>
      </Modal>
    </>
  );
}

export default AnimationModal;
