import React, { useState, useRef, useEffect } from "react";

/**
 * Windows 95/98 style slider component
 * 
 * @param {Object} props
 * @param {number} props.min - Minimum value
 * @param {number} props.max - Maximum value
 * @param {number} props.value - Current value
 * @param {function} props.onChange - Callback when value changes
 * @param {number} props.step - Step size (optional)
 * @param {boolean} props.disabled - Whether the slider is disabled
 * @param {boolean} props.reverse - Reverse the slider direction
 * @param {string} props.className - Additional class names
 */
const Win95Slider = ({ 
  min, 
  max, 
  value, 
  onChange, 
  step = 1, 
  disabled = false,
  reverse = false,
  className = "" 
}) => {
  const trackRef = useRef(null);
  const isDragging = useRef(false);
  
  // Prevent the handle from overlapping at edges
  const handleWidth = 22; // Width of the handle in pixels
  // Add extra margin to prevent handle/button overlap - now using 2/3 of handle width instead of 1/2
  const handleMargin = Math.ceil(handleWidth * 0.67);
  
  // Get a percentage representation of the current value
  const getPercentage = (value) => {
    return ((value - min) / (max - min)) * 100;
  };

  // Convert a percentage back to a value
  const percentToValue = (percent) => {
    const rawValue = ((percent / 100) * (max - min)) + min;
    
    // Round to the nearest step
    const steppedValue = Math.round(rawValue / step) * step;
    
    // Constrain to min/max
    return Math.max(min, Math.min(max, steppedValue));
  };

  // Calculate the current handle position based on value and track bounds
  const calculateHandlePosition = () => {
    if (!trackRef.current) return "0%";
    
    // Get basic percentage from value
    const rawPercentage = getPercentage(value);
    
    // Adjust percentage to account for handle margins
    // Map from 0-100% to handleMargin/width% to (100-handleMargin/width)%
    const adjustedPercentage = ((rawPercentage / 100) * (100 - (2 * handleMargin / trackRef.current.offsetWidth * 100))) + 
                               (handleMargin / trackRef.current.offsetWidth * 100);
    
    return reverse ? `${100 - adjustedPercentage}%` : `${adjustedPercentage}%`;
  };

  // Handle mouse down on the track
  const handleTrackMouseDown = (e) => {
    if (disabled) return;
    
    // Prevent text selection during drag
    e.preventDefault();
    
    const trackRect = trackRef.current.getBoundingClientRect();
    const trackWidth = trackRect.width;
    
    // Calculate the percentage position within the track, with more margin to prevent overlap
    const effectiveTrackWidth = trackWidth - (2 * handleMargin);
    const effectiveLeft = handleMargin;
    const effectiveRight = trackWidth - handleMargin;
    
    // Determine click position within effective track
    const clickPosition = e.clientX - trackRect.left;
    const clampedPosition = Math.max(effectiveLeft, Math.min(effectiveRight, clickPosition));
    
    // Convert to percentage of effective track
    const percentagePosition = ((clampedPosition - effectiveLeft) / effectiveTrackWidth) * 100;
    
    // Calculate and set the value (reverse if needed)
    const newValue = reverse ? 
      percentToValue(100 - percentagePosition) : 
      percentToValue(percentagePosition);
    
    onChange(newValue);
    
    // Start dragging
    isDragging.current = true;
    
    // Setup event listeners for mousemove and mouseup
    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
  };

  // Handle mouse move during drag
  const handleMouseMove = (e) => {
    if (!isDragging.current || !trackRef.current) return;
    
    const trackRect = trackRef.current.getBoundingClientRect();
    const trackWidth = trackRect.width;
    
    // Calculate the percentage position within the track, with more margin to prevent overlap
    const effectiveTrackWidth = trackWidth - (2 * handleMargin);
    const effectiveLeft = handleMargin;
    const effectiveRight = trackWidth - handleMargin;
    
    // Determine mouse position within effective track
    const mousePosition = e.clientX - trackRect.left;
    const clampedPosition = Math.max(effectiveLeft, Math.min(effectiveRight, mousePosition));
    
    // Convert to percentage of effective track
    const percentagePosition = ((clampedPosition - effectiveLeft) / effectiveTrackWidth) * 100;
    
    // Calculate and set the value (reverse if needed)
    const newValue = reverse ? 
      percentToValue(100 - percentagePosition) : 
      percentToValue(percentagePosition);
    
    onChange(newValue);
  };

  // Handle mouse up to end dragging
  const handleMouseUp = () => {
    isDragging.current = false;
    document.removeEventListener('mousemove', handleMouseMove);
    document.removeEventListener('mouseup', handleMouseUp);
  };

  // Clean up event listeners
  useEffect(() => {
    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  return (
    <div 
      className={`win95-slider ${disabled ? 'disabled' : ''} ${className}`}
      style={{
        position: 'relative',
        width: '100%',
        height: '26px',
        cursor: disabled ? 'default' : 'pointer',
        opacity: disabled ? 0.5 : 1,
      }}
    >
      {/* Track */}
      <div
        ref={trackRef}
        className="win95-slider-track"
        style={{
          position: 'absolute',
          left: 0,
          right: 0,
          top: '50%',
          transform: 'translateY(-50%)',
          height: '22px',
          backgroundColor: '#C0C0C0',
          border: '2px solid',
          borderColor: '#808080 #FFFFFF #FFFFFF #808080',
          borderRadius: 0,
        }}
        onMouseDown={handleTrackMouseDown}
      >
        {/* Progress bar */}
        <div
          className="win95-slider-progress"
          style={{
            position: 'absolute',
            left: reverse ? 'auto' : 0,
            right: reverse ? 0 : 'auto',
            top: 0,
            height: '100%',
            width: reverse ? 
              `calc(100% - ${calculateHandlePosition()})` : 
              calculateHandlePosition(),
            backgroundColor: '#C0C0C0',
          }}
        />
        
        {/* Handle */}
        <div
          className="win95-slider-handle"
          style={{
            position: 'absolute',
            left: calculateHandlePosition(),
            top: '50%',
            transform: 'translate(-50%, -50%)',
            width: `${handleWidth}px`,
            height: `${handleWidth}px`,
            backgroundColor: '#C0C0C0',
            border: '2px solid',
            borderColor: '#FFFFFF #808080 #808080 #FFFFFF',
            borderRadius: 0,
            cursor: disabled ? 'default' : 'pointer',
          }}
        />
      </div>
    </div>
  );
};

export default Win95Slider;